sys_transform_script.script:
//The onBefore event script is processed at the start of a row transformation, before the source row is transformed into the target row.
//https://docs.servicenow.com/bundle/xanadu-integrate-applications/page/script/server-scripting/reference/r_MapWithTransformationEventScripts.html
(function runTransformScript(source, map, log, target /*undefined onStart*/ ) {

    const GROUP = {
        OHS_ADVISOR: "13e4414a2f4f68904cbeb1e72799b6f1" //CEH-HRS-OHS-Advisor
    }

    function getPositionManager(position) {
        var jbs = new GlideRecord('sn_hr_core_job');

        if (gs.nil(position.reports_to)) {
            return null;
        }

        //Find manager & assignation
        jbs.addQuery('position', position.reports_to);
        jbs.addQuery('job_active', true);
        jbs.addQuery('user.active', true);
        jbs.query();
        if (jbs.next()) {
            return jbs.user;
        }

        return null;
    }

    function getPositionDescription(position) {
        var description = '';

        description = 'Position: ' + position.position_code.code + ' - ' + position.position_code.name;
        if (position.reports_to && position.reports_to.x_hccc_base_org_position_code) {
            description += '\nReporting to: ' + position.reports_to.x_hccc_base_org_position_code.name;
        }
        if (position.reports_to && position.reports_to.department) {
            description += '\nIn Department: ' + position.reports_to.department.name;
        }

        return description;
    }

    const mgr = getPositionManager(target.position_reporting_position);

    target.assignment_group = GROUP.OHS_ADVISOR; //CEH-HRS-OHS-Advisor
    if (!gs.nil(mgr)) { //manager not found
        target.manager_name = mgr;
    }
    target.short_description = getPositionDescription(target.position_reporting_position);

})(source, map, log, target);
